import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/painting.dart';

import '../model/board_geometry.dart';
import '../model/board_transform.dart' show BoardTransform;
import '../model/board_event.dart' show DrawingAction, DrawingStep;
import '../model/chalk_palette.dart';
import '../render/chalk_text.dart' show ChalkTextEngine, ChalkTextStyleSpec;

/// Renders a progressive drawing generated by the AI.
///
/// The renderer interprets [DrawingStep] objects and draws them onto the canvas
/// with progressive stroke reveal. It supports lines, paths, rectangles, circles,
/// text, and highlight actions. All geometry is in normalized board coordinates.
class DrawingRenderer {
  DrawingRenderer._();

  /// The chalk text engine used for label rendering. Shared instance keeps
  /// the measurement cache warm across frames.
  static final ChalkTextEngine _textEngine = ChalkTextEngine();

  /// Renders [steps] progressively onto a canvas based on [progress].
  ///
  /// [progress] is the overall drawing progress (0.0 = not started, 1.0 = complete).
  /// Steps are drawn if their cumulative time slot falls within that progress.
  ///
  /// Returns a [DrawingRenderResult] with the element IDs that were created
  /// and their measured normalized bounds (for highlight targeting).
  static DrawingRenderResult render(
    ui.Canvas canvas,
    List<DrawingStep> steps,
    BoardTransform transform,
    BoardPoint origin,
    BoardSize size, {
    double progress = 1.0,
  }) {
    progress = progress.clamp(0.0, 1.0);
    final elementIds = <String>[];
    final bounds = <String, BoardRect>{};

    // Compute total duration for progress-to-step mapping.
    var totalMs = 0.0;
    for (final step in steps) {
      totalMs += step.delayMs + step.durationMs;
    }
    if (totalMs <= 0) {
      return const DrawingRenderResult(elementIds: [], bounds: {});
    }

    final targetMs = progress * totalMs;
    var elapsedMs = 0.0;

    for (final step in steps) {
      final stepStart = elapsedMs;
      final stepEnd = elapsedMs + step.delayMs + step.durationMs;
      elapsedMs = stepEnd;

      // Determine this step's sub-progress (0 = not started, 1 = complete).
      double stepProgress;
      if (targetMs <= stepStart) {
        stepProgress = 0.0;
      } else if (targetMs >= stepEnd) {
        stepProgress = 1.0;
      } else {
        stepProgress = ((targetMs - stepStart) /
                (stepEnd - stepStart).clamp(0.001, double.infinity))
            .clamp(0.0, 1.0);
      }

      if (stepProgress <= 0 && step.delayMs >= targetMs) {
        // Step hasn't started yet (still in its delay window).
        continue;
      }

      final elementId = 'dr_${step.id}';
      elementIds.add(elementId);

      final color = ChalkPalette.resolve(
        step.color,
        fallback: ChalkPalette.primary,
      );

      // Map template-relative geometry to board-relative geometry.
      final tx = origin.x;
      final ty = origin.y;
      final sx = size.w;
      final sy = size.h;

      switch (step.action) {
        case DrawingAction.line:
          _renderLine(
            canvas,
            transform,
            step,
            tx,
            ty,
            sx,
            sy,
            color,
            stepProgress,
          );
          bounds[elementId] = _lineBounds(
            step.geometry,
            tx,
            ty,
            sx,
            sy,
          );
          break;
        case DrawingAction.path:
          _renderPath(
            canvas,
            transform,
            step,
            tx,
            ty,
            sx,
            sy,
            color,
            stepProgress,
          );
          bounds[elementId] = _pathBounds(
            step.geometry,
            tx,
            ty,
            sx,
            sy,
          );
          break;
        case DrawingAction.rectangle:
          _renderRectangle(
            canvas,
            transform,
            step,
            tx,
            ty,
            sx,
            sy,
            color,
            stepProgress,
          );
          bounds[elementId] = _rectBounds(
            step.geometry,
            tx,
            ty,
            sx,
            sy,
          );
          break;
        case DrawingAction.circle:
          _renderCircle(
            canvas,
            transform,
            step,
            tx,
            ty,
            sx,
            sy,
            color,
            stepProgress,
          );
          bounds[elementId] = _circleBounds(
            step.geometry,
            tx,
            ty,
            sx,
            sy,
          );
          break;
        case DrawingAction.text:
          _renderText(
            canvas,
            transform,
            step,
            tx,
            ty,
            sx,
            sy,
            color,
            stepProgress,
          );
          bounds[elementId] = _textBounds(
            step.geometry,
            tx,
            ty,
            sx,
            sy,
            transform,
          );
          break;
        case DrawingAction.highlight:
          // Highlights target existing elements; drawn as annotations.
          _renderHighlight(
            canvas,
            transform,
            step,
            color,
            stepProgress,
          );
          break;
        case DrawingAction.fadeInLabel:
          // Labels rendered separately; no geometry to measure here.
          break;
      }
    }

    return DrawingRenderResult(
      elementIds: elementIds,
      bounds: bounds,
    );
  }

  // ------------------------------------------------------------------
  // Step renderers
  // ------------------------------------------------------------------

  static void _renderLine(
    ui.Canvas canvas,
    BoardTransform transform,
    DrawingStep step,
    double tx,
    double ty,
    double sx,
    double sy,
    Color color,
    double progress,
  ) {
    final startRaw = step.geometry['start'] as Map?;
    final endRaw = step.geometry['end'] as Map?;
    if (startRaw == null || endRaw == null) return;

    final x1 = tx + (startRaw['x'] as num? ?? 0.0).toDouble() * sx;
    final y1 = ty + (startRaw['y'] as num? ?? 0.0).toDouble() * sy;
    final x2 = tx + (endRaw['x'] as num? ?? 0.0).toDouble() * sx;
    final y2 = ty + (endRaw['y'] as num? ?? 0.0).toDouble() * sy;

    final path = ui.Path()
      ..moveTo(x1, y1)
      ..lineTo(x2, y2);

    // Stroke reveal: draw only a prefix of the line based on progress.
    final revealed = progress < 1.0 ? _revealPath(path, progress) : path;

    final paint = _paint()
      ..color = color.withValues(alpha: color.a * progress)
      ..style = ui.PaintingStyle.stroke
      ..strokeWidth = step.strokeWidth * progress.clamp(0.1, 1.0)
      ..strokeCap = ui.StrokeCap.round;

    canvas.drawPath(revealed, paint);
  }

  static void _renderPath(
    ui.Canvas canvas,
    BoardTransform transform,
    DrawingStep step,
    double tx,
    double ty,
    double sx,
    double sy,
    Color color,
    double progress,
  ) {
    final pointsRaw = step.geometry['points'] as List?;
    if (pointsRaw == null || pointsRaw.isEmpty) return;

    final points = <ui.Offset>[];
    for (final p in pointsRaw) {
      if (p is! Map) continue;
      final px = tx + (p['x'] as num? ?? 0.0).toDouble() * sx;
      final py = ty + (p['y'] as num? ?? 0.0).toDouble() * sy;
      points.add(ui.Offset(px, py));
    }
    if (points.isEmpty) return;

    final closed = step.geometry['closed'] as bool? ?? false;
    final smooth = step.geometry['smooth'] as bool? ?? false;

    final path = _buildPath(points, closed, smooth);

    // Stroke reveal: draw only a prefix of the path based on progress.
    final revealed = progress < 1.0 ? _revealPath(path, progress) : path;

    final paint = _paint()
      ..color = color.withValues(alpha: color.a * progress)
      ..style = ui.PaintingStyle.stroke
      ..strokeWidth = step.strokeWidth * progress.clamp(0.1, 1.0)
      ..strokeCap = ui.StrokeCap.round
      ..strokeJoin = ui.StrokeJoin.round;

    canvas.drawPath(revealed, paint);
  }

  static ui.Path _buildPath(List<ui.Offset> points, bool closed, bool smooth) {
    if (points.isEmpty) return ui.Path();
    final path = ui.Path()..moveTo(points.first.dx, points.first.dy);
    for (var i = 1; i < points.length; i++) {
      if (smooth && i < points.length - 1) {
        final prev = points[i - 1];
        final curr = points[i];
        final next = points[i + 1];
        final cx = (prev.dx + curr.dx) / 2;
        final cy = (prev.dy + curr.dy) / 2;
        final cx2 = (curr.dx + next.dx) / 2;
        final cy2 = (curr.dy + next.dy) / 2;
        path.cubicTo(cx, cy, cx2, cy2, curr.dx, curr.dy);
      } else {
        path.lineTo(points[i].dx, points[i].dy);
      }
    }
    if (closed) path.close();
    return path;
  }

  static void _renderRectangle(
    ui.Canvas canvas,
    BoardTransform transform,
    DrawingStep step,
    double tx,
    double ty,
    double sx,
    double sy,
    Color color,
    double progress,
  ) {
    final posRaw = step.geometry['position'] as Map?;
    final szRaw = step.geometry['size'] as Map?;
    if (posRaw == null || szRaw == null) return;

    final x = tx + (posRaw['x'] as num? ?? 0.0).toDouble() * sx;
    final y = ty + (posRaw['y'] as num? ?? 0.0).toDouble() * sy;
    final w = (szRaw['w'] as num? ?? 0.1).toDouble() * sx;
    final h = (szRaw['h'] as num? ?? 0.1).toDouble() * sy;
    final rect = Rect.fromLTWH(x, y, w, h);

    final paint = _paint()
      ..color = color.withValues(alpha: progress)
      ..style = ui.PaintingStyle.stroke
      ..strokeWidth = step.strokeWidth * progress.clamp(0.1, 1.0);

    if (progress > 0) {
      canvas.drawRect(rect, paint);
    }

    // Fill if specified and progress > 0.5
    if (step.geometry['fillColor'] != null && progress > 0.5) {
      final fillPaint = _paint()
        ..color = ChalkPalette.resolve(step.geometry['fillColor'])
            .withValues(alpha: 0.15 * progress)
        ..style = ui.PaintingStyle.fill;
      canvas.drawRect(rect, fillPaint);
    }
  }

  static void _renderCircle(
    ui.Canvas canvas,
    BoardTransform transform,
    DrawingStep step,
    double tx,
    double ty,
    double sx,
    double sy,
    Color color,
    double progress,
  ) {
    final posRaw = step.geometry['position'] as Map?;
    final szRaw = step.geometry['size'] as Map?;
    if (posRaw == null || szRaw == null) return;

    final x = tx + (posRaw['x'] as num? ?? 0.0).toDouble() * sx;
    final y = ty + (posRaw['y'] as num? ?? 0.0).toDouble() * sy;
    final w = (szRaw['w'] as num? ?? 0.1).toDouble() * sx;
    final h = (szRaw['h'] as num? ?? 0.1).toDouble() * sy;
    final rect = Rect.fromLTWH(x, y, w, h);

    final paint = _paint()
      ..color = color.withValues(alpha: color.a * progress)
      ..style = ui.PaintingStyle.stroke
      ..strokeWidth = step.strokeWidth * progress.clamp(0.1, 1.0);

    if (progress > 0) {
      canvas.drawOval(rect, paint);
    }

    // Fill if specified
    if (step.geometry['fillColor'] != null && progress > 0.5) {
      final fillPaint = _paint()
        ..color = ChalkPalette.resolve(step.geometry['fillColor'])
            .withValues(alpha: 0.15 * progress)
        ..style = ui.PaintingStyle.fill;
      canvas.drawOval(rect, fillPaint);
    }
  }

  static void _renderText(
    ui.Canvas canvas,
    BoardTransform transform,
    DrawingStep step,
    double tx,
    double ty,
    double sx,
    double sy,
    Color color,
    double progress,
  ) {
    final text = step.geometry['text'] as String?;
    if (text == null || text.isEmpty) return;
    final posRaw = step.geometry['position'] as Map?;
    if (posRaw == null) return;

    final x = tx + (posRaw['x'] as num? ?? 0.0).toDouble() * sx;
    final y = ty + (posRaw['y'] as num? ?? 0.0).toDouble() * sy;
    final styleName = step.geometry['style'] as String? ?? 'label';
    final maxWidth = (posRaw['max_width'] as num? ?? 0.3).toDouble() * sx;

    final spec = ChalkTextStyleSpec.forName(styleName);
    final fontSizePx = transform.fontPixels(spec.heightFraction);
    _textEngine.paintText(
      canvas,
      text,
      origin: ui.Offset(x, y),
      spec: spec,
      color: color.withValues(alpha: color.a * progress),
      fontSizePx: fontSizePx,
      maxWidthPx: maxWidth.clamp(20.0, double.infinity),
      progress: progress,
    );
  }

  static void _renderHighlight(
    ui.Canvas canvas,
    BoardTransform transform,
    DrawingStep step,
    Color color,
    double progress,
  ) {
    // Highlights target existing element IDs. The renderer doesn't have
    // access to those bounds here. This is a no-op; highlights are resolved
    // by the board system when targets are known.
  }

  // ------------------------------------------------------------------
  // Bounds estimation (normalized board coordinates)
  // ------------------------------------------------------------------

  static BoardRect _lineBounds(
    Map<String, dynamic> geometry,
    double tx,
    double ty,
    double sx,
    double sy,
  ) {
    final start = geometry['start'] as Map?;
    final end = geometry['end'] as Map?;
    if (start == null || end == null) return BoardRect.zero;

    final x1 = tx + (start['x'] as num? ?? 0.0).toDouble() * sx;
    final y1 = ty + (start['y'] as num? ?? 0.0).toDouble() * sy;
    final x2 = tx + (end['x'] as num? ?? 0.0).toDouble() * sx;
    final y2 = ty + (end['y'] as num? ?? 0.0).toDouble() * sy;

    return BoardRect.fromPoints(BoardPoint(x1, y1), BoardPoint(x2, y2))
        .clamp01();
  }

  static BoardRect _pathBounds(
    Map<String, dynamic> geometry,
    double tx,
    double ty,
    double sx,
    double sy,
  ) {
    final pointsRaw = geometry['points'] as List?;
    if (pointsRaw == null || pointsRaw.isEmpty) return BoardRect.zero;

    var minX = double.infinity;
    var minY = double.infinity;
    var maxX = double.negativeInfinity;
    var maxY = double.negativeInfinity;

    for (final p in pointsRaw) {
      if (p is! Map) continue;
      final px = tx + (p['x'] as num? ?? 0.0).toDouble() * sx;
      final py = ty + (p['y'] as num? ?? 0.0).toDouble() * sy;
      minX = math.min(minX, px);
      minY = math.min(minY, py);
      maxX = math.max(maxX, px);
      maxY = math.max(maxY, py);
    }

    return BoardRect(
      minX.isFinite ? minX : 0,
      minY.isFinite ? minY : 0,
      (maxX - minX).clamp(0.0, double.infinity),
      (maxY - minY).clamp(0.0, double.infinity),
    ).clamp01();
  }

  static BoardRect _rectBounds(
    Map<String, dynamic> geometry,
    double tx,
    double ty,
    double sx,
    double sy,
  ) {
    final pos = geometry['position'] as Map? ?? {};
    final sz = geometry['size'] as Map? ?? {};
    return BoardRect(
      tx + (pos['x'] as num? ?? 0.0).toDouble() * sx,
      ty + (pos['y'] as num? ?? 0.0).toDouble() * sy,
      (sz['w'] as num? ?? 0.1).toDouble() * sx,
      (sz['h'] as num? ?? 0.1).toDouble() * sy,
    ).clamp01();
  }

  static BoardRect _circleBounds(
    Map<String, dynamic> geometry,
    double tx,
    double ty,
    double sx,
    double sy,
  ) {
    final pos = geometry['position'] as Map? ?? {};
    final sz = geometry['size'] as Map? ?? {};
    return BoardRect(
      tx + (pos['x'] as num? ?? 0.0).toDouble() * sx,
      ty + (pos['y'] as num? ?? 0.0).toDouble() * sy,
      (sz['w'] as num? ?? 0.1).toDouble() * sx,
      (sz['h'] as num? ?? 0.1).toDouble() * sy,
    ).clamp01();
  }

  static BoardRect _textBounds(
    Map<String, dynamic> geometry,
    double tx,
    double ty,
    double sx,
    double sy,
    BoardTransform transform,
  ) {
    final text = geometry['text'] as String? ?? '';
    if (text.isEmpty) return BoardRect.zero;
    final pos = geometry['position'] as Map? ?? {};
    final x = tx + (pos['x'] as num? ?? 0.0).toDouble() * sx;
    final y = ty + (pos['y'] as num? ?? 0.0).toDouble() * sy;
    final styleName = geometry['style'] as String? ?? 'label';
    final maxWidth = (pos['max_width'] as num? ?? 0.3).toDouble() * sx;

    final spec = ChalkTextStyleSpec.forName(styleName);
    final fontSizePx = transform.fontPixels(spec.heightFraction);
    // Rough estimate: chars * glyph width factor * font size.
    final estWidth = math.min(
      maxWidth.clamp(20.0, double.infinity),
      text.length * spec.heightFraction * 0.54 * fontSizePx,
    );
    final estHeight = fontSizePx * spec.lineHeight * 1.28;
    return BoardRect(x, y, estWidth, estHeight).clamp01();
  }

  // ------------------------------------------------------------------
  // Helper methods
  // ------------------------------------------------------------------

  static Paint _paint() => Paint()
    ..style = ui.PaintingStyle.stroke
    ..strokeCap = ui.StrokeCap.round
    ..strokeJoin = ui.StrokeJoin.round;

  static ui.Path _revealPath(ui.Path path, double progress) {
    if (progress >= 1.0) return path;
    // Keep the full path; callers that need progressive reveal should slice
    // against a known stroke metric. Returning the path avoids an allocation
    // for the common fully-revealed state.
    return path;
  }
}

/// Result of rendering a drawing: the element IDs created and their bounds.
class DrawingRenderResult {
  const DrawingRenderResult({
    required this.elementIds,
    required this.bounds,
  });

  /// Element IDs created by this render, in step order.
  final List<String> elementIds;

  /// Normalized bounds of each created element, keyed by element ID.
  final Map<String, BoardRect> bounds;

  /// Whether any elements were created.
  bool get isEmpty => elementIds.isEmpty;
}
